local PlayerLifeTimeService = {}
PlayerLifeTimeService.__index = PlayerLifeTimeService

function PlayerLifeTimeService.new()
	local self = setmetatable({}, PlayerLifeTimeService)
	self._services = {}
	return self
end

-- 获取玩家生命周期内, 按顺序执行的服务
function PlayerLifeTimeService:GetServiceNames(): { string }
	return self._lifeTimeProvider
end

-- 设置玩家生命周期内, 按顺序执行的服务
function PlayerLifeTimeService:SetLifeTimeProvider(lifeTimeProvider: { string } | (player: Player) -> { string })
	self._lifeTimeProvider = lifeTimeProvider
end

function PlayerLifeTimeService:RunLifeTimeServices(player: Player, serviceProvider: ServiceProvider)
	local result = {}

	if not self._lifeTimeProvider then
		return
	end

	local serviceNames = self._lifeTimeProvider

	if type(self._lifeTimeProvider) == "function" then
		serviceNames = self._lifeTimeProvider(player)
	end

	for _, serviceName in serviceNames do
		-- 等待, 以检查服务执行后玩家是否在线了.
		task.wait()

		if not game.Players:GetPlayers(player.UserId) then
			return
		end

		table.insert(result, serviceProvider:GetRequiredService(serviceName))
	end
	return result
end

export type Type = typeof(PlayerLifeTimeService.new())

return PlayerLifeTimeService
